export async function setupGiftCodes(){const db=new PGlite();await db.exec(`create role anon;create role authenticated;create role service_role;create schema auth;create table auth.users(id uuid primary key,email text,created_at timestamptz default now(),last_sign_in_at timestamptz,raw_app_meta_data jsonb default '{}');create table coaching_remote_users(id uuid primary key,display_name text,qa boolean,enabled boolean);create table v2_personal_records(owner_id uuid,kind text,id uuid,deleted_at timestamptz,updated_at timestamptz);create table v2_personal_commands(owner_id uuid,created_at timestamptz);create table coaching_remote_sessions(id uuid,owner_id uuid,state jsonb,updated_at timestamptz);`);for(const p of ['supabase/migrations/20261016191733_v2_admin_rights_block5.sql','docs/member-gifts-proposal/01-owner-gifts.proposed.sql'])await db.exec(await readFile(new URL(p,root),'utf8'));try{await db.exec(await readFile(new URL('docs/real-gift-codes/01-premium-codes.proposed.sql',root),'utf8'));}catch(e){if(e.code!=='ENOENT')throw e;}
for(const [id,meta] of [[owner,{admin_role:'owner_admin'}],[member,{}],[other,{permissions:{research:true},premium_entitlement:{entitlement:'premium',source:'premium',granted_at:'2026-01-01',expires_at:'2099-01-01'}}],[disabled,{}]]){await db.query('insert into auth.users(id,raw_app_meta_data) values($1,$2)',[id,meta]);await db.query('insert into coaching_remote_users values($1,$2,false,$3)',[id,id,id!==disabled]);}return db;}
